"""Visualize the evaluation metrics generated by evaluate.py.

This script reads `eval_results.json` from the `eval_outputs` folder and 
generates four summary charts (pie chart, top-10 bar chart, confidence histogram, 
and precision-vs-recall scatter plot) to make the results easier to interpret.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import seaborn as sns
from matplotlib.cm import ScalarMappable
from matplotlib.colors import Normalize

SCRIPT_DIR = Path(__file__).resolve().parent
OUTPUT_DIR = SCRIPT_DIR / "eval_outputs"
RESULTS_PATH = OUTPUT_DIR / "eval_results.json"


def load_results() -> dict[str, Any]:
    """Load the evaluation results and fail with a useful message if absent."""
    if not RESULTS_PATH.exists():
        raise FileNotFoundError(
            f"Could not find {RESULTS_PATH}. Run evaluate.py first."
        )

    with RESULTS_PATH.open(encoding="utf-8") as handle:
        return json.load(handle)


def find_confidence_values(node: Any) -> list[float] | None:
    """Look for a list of confidence scores anywhere in the JSON.

    The current evaluation output does not include per-image confidences, so
    this usually returns None and the histogram falls back to F1 scores.
    """
    if isinstance(node, dict):
        for key, value in node.items():
            if "confidence" in key.lower():
                values = as_numeric_list(value)
                if values:
                    return values

            found = find_confidence_values(value)
            if found:
                return found

    elif isinstance(node, list):
        values = as_numeric_list(node)
        if values:
            return values

        for item in node:
            found = find_confidence_values(item)
            if found:
                return found

    return None


def as_numeric_list(value: Any) -> list[float] | None:
    """Return a plain list of floats when the value looks like one."""
    if not isinstance(value, list) or not value:
        return None

    if all(isinstance(item, (int, float)) for item in value):
        return [float(item) for item in value]

    # A common alternative shape is a list of prediction dictionaries.
    if all(
        isinstance(item, dict)
        and isinstance(item.get("confidence"), (int, float))
        for item in value
    ):
        return [float(item["confidence"]) for item in value]

    return None


def save_pie_chart(results: dict[str, Any]) -> Path:
    """Show the split between correct and incorrect top-1 predictions."""
    top1_accuracy = float(results["top1_accuracy"])
    correct_pct = top1_accuracy * 100.0
    incorrect_pct = 100.0 - correct_pct

    total = results.get("num_images_evaluated")
    if isinstance(total, int) and total > 0:
        correct_count = int(round(top1_accuracy * total))
        incorrect_count = total - correct_count
        labels = [
            f"Correct\n{correct_count} images",
            f"Incorrect\n{incorrect_count} images",
        ]
    else:
        labels = ["Correct", "Incorrect"]

    fig, ax = plt.subplots(figsize=(6.5, 6.5))
    ax.pie(
        [correct_pct, incorrect_pct],
        labels=labels,
        colors=["#2A9D8F", "#E76F51"],
        autopct="%1.1f%%",
        startangle=90,
        wedgeprops={"edgecolor": "white", "linewidth": 2},
        textprops={"fontsize": 11},
    )
    ax.set_title("Top-1 Prediction Outcomes", fontsize=14, fontweight="bold")
    ax.axis("equal")

    path = OUTPUT_DIR / "pie_chart.png"
    fig.savefig(path, dpi=200, bbox_inches="tight")
    plt.close(fig)
    return path


def save_top10_bar_chart(results: dict[str, Any]) -> Path:
    """Plot the ten classes with the highest F1 scores."""
    per_class = results.get("per_class") or {}
    if not per_class:
        raise ValueError("eval_results.json does not contain per_class data.")

    ranked = sorted(
        per_class.items(),
        key=lambda item: float(item[1].get("f1_score", 0.0)),
        reverse=True,
    )[:10]

    names = [name.replace("_", " ").title() for name, _ in ranked]
    scores = [float(metrics.get("f1_score", 0.0)) for _, metrics in ranked]

    fig, ax = plt.subplots(figsize=(10, 5.5))
    sns.barplot(
        x=scores,
        y=names,
        hue=names,
        palette="viridis",
        legend=False,
        ax=ax,
    )

    for index, score in enumerate(scores):
        ax.text(
            score + 0.01,
            index,
            f"{score:.3f}",
            va="center",
            fontsize=9,
            color="#333333",
        )

    ax.set_xlim(0, 1.08)
    ax.set_xlabel("F1 score")
    ax.set_ylabel("")
    ax.set_title(
        "Top 10 Easiest Food Categories (Highest F1 Score)",
        fontsize=14,
        fontweight="bold",
    )
    ax.grid(axis="x", linestyle="--", alpha=0.4)

    path = OUTPUT_DIR / "top10_bar.png"
    fig.savefig(path, dpi=200, bbox_inches="tight")
    plt.close(fig)
    return path


def save_histogram(results: dict[str, Any]) -> Path:
    """Plot confidence scores when available, otherwise per-class F1 scores."""
    confidence_values = find_confidence_values(results)

    if confidence_values:
        values = confidence_values
        if max(values) > 1.0:
            values = [value / 100.0 for value in values]
        xlabel = "Top-1 confidence"
        ylabel = "Number of images"
        title = "Distribution of Top-1 Confidence Scores"
    else:
        per_class = results.get("per_class") or {}
        values = [
            float(metrics.get("f1_score", 0.0))
            for metrics in per_class.values()
        ]
        if not values:
            raise ValueError(
                "No confidence scores or per-class F1 scores were found."
            )
        xlabel = "F1 score"
        ylabel = "Number of categories"
        title = "Distribution of Per-Class F1 Scores"

    mean_value = float(np.mean(values))
    median_value = float(np.median(values))

    fig, ax = plt.subplots(figsize=(8.5, 5.5))
    sns.histplot(
        values,
        bins=20,
        kde=True,
        color="#457B9D",
        edgecolor="white",
        linewidth=0.8,
        ax=ax,
    )
    ax.axvline(
        mean_value,
        color="#E76F51",
        linestyle="--",
        linewidth=1.5,
        label=f"Mean: {mean_value:.3f}",
    )
    ax.axvline(
        median_value,
        color="#1D3557",
        linestyle=":",
        linewidth=1.5,
        label=f"Median: {median_value:.3f}",
    )
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    ax.set_title(title, fontsize=14, fontweight="bold")
    ax.legend()

    path = OUTPUT_DIR / "histogram.png"
    fig.savefig(path, dpi=200, bbox_inches="tight")
    plt.close(fig)
    return path


def save_precision_recall_scatter(results: dict[str, Any]) -> Path:
    """Plot precision against recall for every class, coloured by F1 score."""
    per_class = results.get("per_class") or {}
    if not per_class:
        raise ValueError("eval_results.json does not contain per_class data.")

    precisions = [
        float(metrics.get("precision", 0.0))
        for metrics in per_class.values()
    ]
    recalls = [
        float(metrics.get("recall", 0.0))
        for metrics in per_class.values()
    ]
    f1_scores = [
        float(metrics.get("f1_score", 0.0))
        for metrics in per_class.values()
    ]

    fig, ax = plt.subplots(figsize=(8.5, 7))
    sns.scatterplot(
        x=precisions,
        y=recalls,
        hue=f1_scores,
        palette="viridis",
        hue_norm=(0.0, 1.0),
        s=80,
        edgecolor="white",
        linewidth=0.6,
        legend=False,
        ax=ax,
    )

    # The diagonal is a useful reference: points near it have similar
    # precision and recall.
    ax.plot(
        [0.0, 1.05],
        [0.0, 1.05],
        linestyle="--",
        color="#666666",
        linewidth=1.2,
        alpha=0.8,
    )

    ax.set_xlim(0.0, 1.05)
    ax.set_ylim(0.0, 1.05)
    ax.set_xlabel("Precision")
    ax.set_ylabel("Recall")
    ax.set_title(
        "Precision vs. Recall by Food Category",
        fontsize=14,
        fontweight="bold",
    )
    ax.set_aspect("equal", adjustable="box")
    ax.grid(True, linestyle="--", alpha=0.35)

    norm = Normalize(vmin=0.0, vmax=1.0)
    scalar_map = ScalarMappable(norm=norm, cmap=plt.get_cmap("viridis"))
    scalar_map.set_array([])
    colorbar = fig.colorbar(scalar_map, ax=ax, pad=0.02)
    colorbar.set_label("F1 score")

    path = OUTPUT_DIR / "precision_vs_recall.png"
    fig.savefig(path, dpi=200, bbox_inches="tight")
    plt.close(fig)
    return path


def main() -> int:
    sns.set_theme(style="whitegrid", context="notebook")
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

    results = load_results()

    paths = [
        save_pie_chart(results),
        save_top10_bar_chart(results),
        save_histogram(results),
        save_precision_recall_scatter(results),
    ]

    for path in paths:
        print(f"Saved {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
